// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0, 0, 1000, 780);
var g = draw.group();

var stageIndex = 0;   // 0 T(n),1 one split,2 two splits,3 full tree
var k = 4;            // n = 2^k
var overlay = false;
var CAPTIONS = ['(a)', '(b)', '(c)', '(d)'];

var ROOT = { x: 430, y: 90 };
var L1 = [{ x: 290, y: 230 }, { x: 570, y: 230 }];
var L2 = [{ x: 220, y: 370 }, { x: 360, y: 370 }, { x: 500, y: 370 }, { x: 640, y: 370 }];
var LEAF_Y = 640;
var LEAF_L = 150, LEAF_R = 710;

function txt(x, y, s, o) {
  o = o || {};
  var t = g.text(s)
    .font({ family: 'Georgia, "Times New Roman", serif', style: 'italic', size: o.size || 22, weight: o.bold ? 'bold' : 'normal' })
    .attr({ 'text-anchor': o.anchor || 'middle', fill: o.fill || '#000', x: x, y: y });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return t;
}
function edge(x1, y1, x2, y2, dashed) {
  var l = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 1.1 });
  if (dashed) l.attr('stroke-dasharray', '4,4');
  return l;
}
function band(y) {
  g.rect(640, 36).attr({ x: 110, y: y - 18, fill: '#fff3c4', opacity: 0.55, rx: 4 });
}
function hArrow(y) {
  g.line(745, y, 855, y).stroke({ color: '#000', width: 1.4 }).attr('stroke-dasharray', '2,4');
  g.polygon('862,' + y + ' 852,' + (y - 4) + ' 852,' + (y + 4)).fill('#000');
  txt(888, y + 7, 'cn', { size: 22, halo: true })
    .on('mousemove', function (e) { showTooltip('This whole level sums to cn.', e); })
    .on('mouseleave', hideTooltip);
}

function leafColumns() {
  var n = Math.pow(2, k);
  if (n <= 8) {
    var xs = [];
    for (var i = 0; i < n; i++) xs.push(LEAF_L + i * (560 / (n - 1 || 1)));
    return { xs: xs, ellipsis: false };
  }
  return { xs: [150, 220, 290, 360, 500, 570, 640, 710], ellipsis: true };
}

function render() {
  g.clear();
  var n = Math.pow(2, k);

  // highlight bands (under everything) when overlay on
  if (overlay) {
    band(ROOT.y);
    if (stageIndex >= 1) band(230);
    if (stageIndex >= 2) band(370);
    if (stageIndex >= 3) band(LEAF_Y);
  }

  if (stageIndex === 0) {
    txt(ROOT.x, ROOT.y + 8, 'T(n)', { size: 28, halo: true })
      .on('mousemove', function (e) { showTooltip('The whole problem: T(n) = 2T(n/2) + cn.', e); })
      .on('mouseleave', hideTooltip);
  } else {
    // root cost node
    txt(ROOT.x, ROOT.y + 8, 'cn', { size: 24, halo: true })
      .on('mousemove', function (e) { showTooltip('Work done at the root level before recursing: cn.', e); })
      .on('mouseleave', hideTooltip);
    // edges root -> L1
    edge(ROOT.x - 12, ROOT.y + 14, L1[0].x + 8, L1[0].y - 14);
    edge(ROOT.x + 12, ROOT.y + 14, L1[1].x - 8, L1[1].y - 14);

    for (var a = 0; a < 2; a++) {
      if (stageIndex === 1) {
        txt(L1[a].x, L1[a].y + 8, 'T(n/2)', { size: 22, halo: true });
      } else {
        txt(L1[a].x, L1[a].y + 8, 'cn/2', { size: 22, halo: true });
        edge(L1[a].x - 10, L1[a].y + 14, L2[2 * a].x + 8, L2[2 * a].y - 14);
        edge(L1[a].x + 10, L1[a].y + 14, L2[2 * a + 1].x - 8, L2[2 * a + 1].y - 14);
        for (var b = 0; b < 2; b++) {
          var node = L2[2 * a + b];
          if (stageIndex === 2) {
            txt(node.x, node.y + 8, 'T(n/4)', { size: 22, halo: true });
          } else {
            txt(node.x, node.y + 8, 'cn/4', { size: 22, halo: true });
            // dashed stubs implying further expansion
            edge(node.x - 8, node.y + 14, node.x - 16, node.y + 64, true);
            edge(node.x + 8, node.y + 14, node.x + 16, node.y + 64, true);
          }
        }
      }
    }
  }

  if (stageIndex === 3) {
    var lc = leafColumns();
    // vertical dashed continuation lines
    for (var v = 0; v < lc.xs.length; v++) {
      edge(lc.xs[v], 440, lc.xs[v], 610, true);
    }
    // leaf row
    for (var L = 0; L < lc.xs.length; L++) {
      txt(lc.xs[L], LEAF_Y + 7, 'c', { size: 20, halo: true });
    }
    if (lc.ellipsis) txt(430, LEAF_Y + 7, '···', { size: 22, halo: true });

    // horizontal brace under leaves
    var bx1 = LEAF_L - 12, bx2 = LEAF_R + 12, by = LEAF_Y + 26, cxm = 430;
    g.path('M ' + bx1 + ' ' + by +
      ' Q ' + bx1 + ' ' + (by + 12) + ' ' + (bx1 + 16) + ' ' + (by + 12) +
      ' L ' + (cxm - 16) + ' ' + (by + 12) +
      ' Q ' + cxm + ' ' + (by + 12) + ' ' + cxm + ' ' + (by + 22) +
      ' Q ' + cxm + ' ' + (by + 12) + ' ' + (cxm + 16) + ' ' + (by + 12) +
      ' L ' + (bx2 - 16) + ' ' + (by + 12) +
      ' Q ' + bx2 + ' ' + (by + 12) + ' ' + bx2 + ' ' + by)
      .fill('none').stroke({ color: '#000', width: 1.1 });
    txt(cxm, by + 44, 'n', { size: 22, halo: true });

    // left double-headed height arrow
    var ax = 70;
    g.line(ax, ROOT.y, ax, LEAF_Y).stroke({ color: '#000', width: 1.2 });
    g.polygon(ax + ',' + (ROOT.y - 6) + ' ' + (ax - 4) + ',' + (ROOT.y + 4) + ' ' + (ax + 4) + ',' + (ROOT.y + 4)).fill('#000');
    g.polygon(ax + ',' + (LEAF_Y + 6) + ' ' + (ax - 4) + ',' + (LEAF_Y - 4) + ' ' + (ax + 4) + ',' + (LEAF_Y - 4)).fill('#000');
    txt(38, (ROOT.y + LEAF_Y) / 2 + 6, 'lg n', { size: 20, halo: true });
  }

  // right per-level cost column
  if (overlay) {
    hArrow(ROOT.y);
    if (stageIndex >= 1) hArrow(230);
