    g.polygon(ax + ',' + (ROOT.y - 6) + ' ' + (ax - 4) + ',' + (ROOT.y + 4) + ' ' + (ax + 4) + ',' + (ROOT.y + 4)).fill('#000');
    g.polygon(ax + ',' + (LEAF_Y + 6) + ' ' + (ax - 4) + ',' + (LEAF_Y - 4) + ' ' + (ax + 4) + ',' + (LEAF_Y - 4)).fill('#000');
    txt(38, (ROOT.y + LEAF_Y) / 2 + 6, 'lg n', { size: 20, halo: true });
  }

  // right per-level cost column
  if (overlay) {
    hArrow(ROOT.y);
    if (stageIndex >= 1) hArrow(230);
    if (stageIndex >= 2) hArrow(370);
    if (stageIndex >= 3) {
      // vertical ellipsis between last internal level and leaves
      for (var d = 0; d < 3; d++) g.circle(4).attr({ cx: 895, cy: 480 + d * 20, fill: '#000' });
      hArrow(LEAF_Y);
      g.line(855, LEAF_Y + 24, 935, LEAF_Y + 24).stroke({ color: '#000', width: 1.2 });
      txt(895, LEAF_Y + 50, 'Total: cn lg n + cn', { size: 20, halo: true, bold: true })
        .on('mousemove', function (e) { showTooltip('(lg n + 1) levels each costing cn → cn·lg n + cn = Θ(n lg n).', e); })
        .on('mouseleave', hideTooltip);
    }
  }

  // stage caption
  txt(430, 768, CAPTIONS[stageIndex], { size: 20, bold: true });
}

/* ---- interactions ---- */
function trigger_expansionStage() { stageIndex = (stageIndex + 1) % 4; render(); }
function update_problemSize(v) {
  k = +v;
  document.getElementById('problemSizeVal').value = Math.pow(2, k);
  render();
}
function toggle_levelCostOverlay(on) { overlay = !!on; render(); }

/* ---- demo step player ---- */
var STAGE_IDX = { 'T(n)': 0, 'One split': 1, 'Two splits': 2, 'Full tree': 3 };
var steps = [
  { title: 'Start from the recurrence', narration: 'We begin with the single term T(n). The recurrence says each call does cn work and spawns two calls on half the input.', state: { expansionStage: 'T(n)', levelCostOverlay: false, problemSize: 4 } },
  { title: 'First expansion', narration: 'Replacing T(n) gives a root cost cn with two children T(n/2). The cn at the top is the work done at this level before recursing.', state: { expansionStage: 'One split', levelCostOverlay: false, problemSize: 4 } },
  { title: 'Second expansion', narration: 'Each T(n/2) becomes cn/2 with two T(n/4) children. Notice the two cn/2 nodes on this level already add back up to cn.', state: { expansionStage: 'Two splits', levelCostOverlay: false, problemSize: 4 } },
  { title: 'The full tree', narration: 'Continuing to the leaves yields a tree of height lg n whose bottom row holds n leaves each costing c. The left arrow marks the height; the brace marks the n leaves.', state: { expansionStage: 'Full tree', levelCostOverlay: false, problemSize: 4 } },
  { title: 'Reveal the level sums', narration: 'Switch on the per-level column: every row totals exactly cn. Stacking lg n + 1 such rows gives Total = cn lg n + cn = Θ(n lg n).', state: { expansionStage: 'Full tree', levelCostOverlay: true, problemSize: 4 } },
  { title: 'Grow the input', narration: 'Slide n upward: the tree gains a level and a doubled leaf row, the lg n arrow lengthens, and the total expression grows in lockstep, confirming height alone drives the cost.', state: { expansionStage: 'Full tree', levelCostOverlay: true, problemSize: 6 } }
];
var curStep = 0;
function applyStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep].state;
  stageIndex = STAGE_IDX[s.expansionStage];
  overlay = !!s.levelCostOverlay;
  k = +s.problemSize;
  document.getElementById('problemSizeInput').value = k;
  document.getElementById('problemSizeVal').value = Math.pow(2, k);
  document.getElementById('levelCostOverlayInput').checked = overlay;
  document.getElementById('demoNarration').textContent = steps[curStep].narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + steps.length;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

