userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="expansionStageInput" onclick="trigger_expansionStage()">Expand recurrence</button>
<label>Problem size n (power of two): <output id="problemSizeVal">16</output>
<input id="problemSizeInput" type="range" min="2" max="6" step="1" value="4" oninput="update_problemSize(+this.value)"></label>
<label><input id="levelCostOverlayInput" type="checkbox" onchange="toggle_levelCostOverlay(this.checked)"> Show per-level cost column</label>
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"></p>
<div style="display:flex;gap:4px;align-items:center">
<button onclick="prevStep()">◀</button><span id="stepLabel"></span><button onclick="nextStep()">▶</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1000, 780);
var g = draw.group();

var stageIndex = 0;   // 0 T(n),1 one split,2 two splits,3 full tree
var k = 4;            // n = 2^k
var overlay = false;  // per-level cost column (auto-on at full tree)
var CAPTIONS = ['(a)', '(b)', '(c)', '(d)'];

var ROOT_Y = 80, LEVEL_GAP = 95, CX = 430;
var LEAF_L = 150, LEAF_R = 710;

function yFor(i) { return ROOT_Y + i * LEVEL_GAP; }
function leafY() { return yFor(k); }
function drawnInternal() { return Math.min(3, k); } // explicit cost levels: cn, cn/2, cn/4

// x-positions of the explicitly drawn internal levels (match source geometry)
function levelXs(i) {
  if (i === 0) return [CX];
  if (i === 1) return [CX - 140, CX + 140];
  if (i === 2) return [CX - 210, CX - 70, CX + 70, CX + 210];
  return leafColumns().xs; // i >= 3 → leaf row
}
function leafColumns() {
  var n = Math.pow(2, k);
  if (n <= 8) {
    var xs = [];
    for (var i = 0; i < n; i++) xs.push(LEAF_L + i * ((LEAF_R - LEAF_L) / (n - 1 || 1)));
    return { xs: xs, ellipsis: false, n: n };
  }
  // representative 8 columns + centred ellipsis standing for the remaining leaves
  return { xs: [150, 215, 280, 345, 515, 580, 645, 710], ellipsis: true, n: n };
}
function costLabel(i) { return i === 0 ? 'cn' : (i === 1 ? 'cn/2' : 'cn/4'); }

function txt(x, y, s, o) {
  o = o || {};
  var t = g.text(s)
    .font({ family: 'Georgia, "Times New Roman", serif', style: 'italic', size: o.size || 22, weight: o.bold ? 'bold' : 'normal' })
    .attr({ 'text-anchor': o.anchor || 'middle', fill: o.fill || '#000', x: x, y: y });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return t;
}
function edge(x1, y1, x2, y2, dashed) {
  var l = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 1.1 });
  if (dashed) l.attr('stroke-dasharray', '4,4');
  return l;
}
function band(y) {
  g.rect(620, 36).attr({ x: 120, y: y - 18, fill: '#fff3c4', opacity: 0.55, rx: 4 });
}
function hArrow(y, startX) {
  g.line(startX, y, 855, y).stroke({ color: '#000', width: 1.4 }).attr('stroke-dasharray', '2,4');
  g.polygon('862,' + y + ' 852,' + (y - 4) + ' 852,' + (y + 4)).fill('#000');
  txt(895, y + 7, 'cn', { size: 22, halo: true })
    .on('mousemove', function (e) { showTooltip('This whole level sums to cn.', e); })
    .on('mouseleave', hideTooltip);
}

function render() {
  g.clear();
  var n = Math.pow(2, k);
  var ly = leafY();
  var di = drawnInternal();
  var showCol = overlay;

  // highlight bands (under everything) when column shown
  if (showCol && stageIndex >= 1) {
    band(ROOT_Y);
    if (stageIndex >= 1) band(yFor(1));
    if (stageIndex >= 2) band(yFor(2));
    if (stageIndex === 3) band(ly);
  }

  if (stageIndex === 0) {
    txt(CX, ROOT_Y + 8, 'T(n)', { size: 28, halo: true })
      .on('mousemove', function (e) { showTooltip('The whole problem: T(n) = 2T(n/2) + cn.', e); })
      .on('mouseleave', hideTooltip);
  } else {
    // root cost node
    txt(CX, ROOT_Y + 8, 'cn', { size: 24, halo: true })
      .on('mousemove', function (e) { showTooltip('Work done at the root level before recursing: cn.', e); })
      .on('mouseleave', hideTooltip);

    // edges root -> level 1
    var l1 = levelXs(1);
    edge(CX - 12, ROOT_Y + 14, l1[0] + 8, yFor(1) - 14);
    edge(CX + 12, ROOT_Y + 14, l1[1] - 8, yFor(1) - 14);

    for (var a = 0; a < 2; a++) {
      if (stageIndex === 1) {
        txt(l1[a], yFor(1) + 8, 'T(n/2)', { size: 22, halo: true });
      } else {
        txt(l1[a], yFor(1) + 8, 'cn/2', { size: 22, halo: true });
        if (di >= 2) {
          var l2 = levelXs(2);
          edge(l1[a] - 10, yFor(1) + 14, l2[2 * a] + 8, yFor(2) - 14);
          edge(l1[a] + 10, yFor(1) + 14, l2[2 * a + 1] - 8, yFor(2) - 14);
          for (var b = 0; b < 2; b++) {
            var nx = l2[2 * a + b];
            if (stageIndex === 2) {
              txt(nx, yFor(2) + 8, 'T(n/4)', { size: 22, halo: true });
            } else {
              txt(nx, yFor(2) + 8, 'cn/4', { size: 22, halo: true });
            }
          }
        }
      }
    }
  }

  if (stageIndex === 3) {
    var lastLevel = di - 1;            // deepest explicitly drawn cost level
    var lastY = yFor(lastLevel);
    var lastXs = levelXs(lastLevel);
    // short dashed stubs below the deepest drawn cost level (imply next split)
    for (var s = 0; s < lastXs.length; s++) {
      edge(lastXs[s] - 8, lastY + 14, lastXs[s] - 16, lastY + 56, true);
      edge(lastXs[s] + 8, lastY + 14, lastXs[s] + 16, lastY + 56, true);
    }
    var lc = leafColumns();
    // vertical dashed continuation lines down to each leaf column
    for (var v = 0; v < lc.xs.length; v++) {
      edge(lc.xs[v], lastY + 70, lc.xs[v], ly - 28, true);
    }
    // leaf row
    for (var L = 0; L < lc.xs.length; L++) txt(lc.xs[L], ly + 7, 'c', { size: 20, halo: true });
    if (lc.ellipsis) txt(CX, ly + 7, '···', { size: 22, halo: true });

    // horizontal brace under leaves, width tied to leaf positions
    var bx1 = Math.min.apply(null, lc.xs) - 14, bx2 = Math.max.apply(null, lc.xs) + 14;
    var by = ly + 26, cxm = (bx1 + bx2) / 2;
    g.path('M ' + bx1 + ' ' + by +
      ' Q ' + bx1 + ' ' + (by + 12) + ' ' + (bx1 + 16) + ' ' + (by + 12) +
      ' L ' + (cxm - 16) + ' ' + (by + 12) +
      ' Q ' + cxm + ' ' + (by + 12) + ' ' + cxm + ' ' + (by + 22) +
      ' Q ' + cxm + ' ' + (by + 12) + ' ' + (cxm + 16) + ' ' + (by + 12) +
      ' L ' + (bx2 - 16) + ' ' + (by + 12) +
      ' Q ' + bx2 + ' ' + (by + 12) + ' ' + bx2 + ' ' + by)
      .fill('none').stroke({ color: '#000', width: 1.1 });
    txt(cxm, by + 44, 'n', { size: 22, halo: true });

    // left double-headed height arrow spanning root -> leaves (lengthens with k)
    var ax = 70;
    g.line(ax, ROOT_Y, ax, ly).stroke({ color: '#000', width: 1.2 });
    g.polygon(ax + ',' + (ROOT_Y - 6) + ' ' + (ax - 4) + ',' + (ROOT_Y + 4) + ' ' + (ax + 4) + ',' + (ROOT_Y + 4)).fill('#000');
    g.polygon(ax + ',' + (ly + 6) + ' ' + (ax - 4) + ',' + (ly - 4) + ' ' + (ax + 4) + ',' + (ly - 4)).fill('#000');
    txt(38, (ROOT_Y + ly) / 2 + 6, 'lg n', { size: 20, halo: true });
  }

  // right per-level cost column
  if (showCol && stageIndex >= 1) {
    hArrow(ROOT_Y, CX + 40);
    if (stageIndex >= 1) hArrow(yFor(1), levelXs(1)[1] + 40);
    if (stageIndex >= 2 && di >= 2) hArrow(yFor(2), levelXs(2)[3] + 40);
    if (stageIndex === 3) {
      // vertical ellipsis for the un-drawn levels between last cost level and leaves
      if (k >= 4) for (var d = 0; d < 3; d++) g.circle(4).attr({ cx: 895, cy: (yFor(2) + ly) / 2 - 20 + d * 20, fill: '#000' });
      hArrow(ly, Math.max.apply(null, leafColumns().xs) + 35);
      g.line(855, ly + 24, 935, ly + 24).stroke({ color: '#000', width: 1.2 });
      txt(895, ly + 50, 'Total: cn lg n + cn', { size: 20, halo: true, bold: true })
        .on('mousemove', function (e) { showTooltip('(lg n + 1) levels each costing cn → cn·lg n + cn = Θ(n lg n). Here lg n = ' + k + '.', e); })
        .on('mouseleave', hideTooltip);
    }
  }

  txt(CX, 768, CAPTIONS[stageIndex], { size: 20, bold: true });
}

/* ---- interactions ---- */
function syncCheckbox() { document.getElementById('levelCostOverlayInput').checked = overlay; }
function setStage(idx) {
  stageIndex = idx;
  if (idx === 3) overlay = true;       // auto-enable column so panel (d) matches source
  else if (idx === 0) overlay = false; // clean single-term view
  syncCheckbox();
  render();
}
function trigger_expansionStage() { setStage((stageIndex + 1) % 4); }
function update_problemSize(v) {
  k = +v;
  document.getElementById('problemSizeVal').value = Math.pow(2, k);
  render();
}
function toggle_levelCostOverlay(on) { overlay = !!on; render(); }

/* ---- demo step player ---- */
var STAGE_IDX = { 'T(n)': 0, 'One split': 1, 'Two splits': 2, 'Full tree': 3 };
var steps = [
  { title: 'Start from the recurrence', narration: 'We begin with the single term T(n). The recurrence says each call does cn work and spawns two calls on half the input.', state: { expansionStage: 'T(n)', levelCostOverlay: false, problemSize: 4 } },
  { title: 'First expansion', narration: 'Replacing T(n) gives a root cost cn with two children T(n/2). The cn at the top is the work done at this level before recursing.', state: { expansionStage: 'One split', levelCostOverlay: false, problemSize: 4 } },
  { title: 'Second expansion', narration: 'Each T(n/2) becomes cn/2 with two T(n/4) children. Notice the two cn/2 nodes on this level already add back up to cn.', state: { expansionStage: 'Two splits', levelCostOverlay: false, problemSize: 4 } },
  { title: 'The full tree', narration: 'Continuing to the leaves yields a tree of height lg n whose bottom row holds n leaves each costing c. The left arrow marks the height; the brace marks the n leaves.', state: { expansionStage: 'Full tree', levelCostOverlay: true, problemSize: 4 } },
  { title: 'Reveal the level sums', narration: 'Every row totals exactly cn. Stacking lg n + 1 such rows gives Total = cn lg n + cn = Θ(n lg n).', state: { expansionStage: 'Full tree', levelCostOverlay: true, problemSize: 4 } },
  { title: 'Grow the input', narration: 'Slide n upward: the tree gains levels and a doubled leaf row, the lg n arrow lengthens, and the total grows in lockstep — height alone drives the cost.', state: { expansionStage: 'Full tree', levelCostOverlay: true, problemSize: 6 } }
];
var curStep = 0;
function applyStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep].state;
  k = +s.problemSize;
  document.getElementById('problemSizeInput').value = k;
  document.getElementById('problemSizeVal').value = Math.pow(2, k);
  setStage(STAGE_IDX[s.expansionStage]);   // auto-enables column at full tree
  overlay = !!s.levelCostOverlay || (stageIndex === 3); // honour step intent, default on at (d)
  syncCheckbox();
  render();
  document.getElementById('demoNarration').textContent = steps[curStep].narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + steps.length;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

